  @ffi.Int()
  external int status;

  external ffi.Pointer<ffi.Char> json;

  static ffi.Pointer<AuthJsonResult> $allocate(
    ffi.Allocator $allocator, {
    required int status,
    required ffi.Pointer<ffi.Char> json,
  }) => $allocator<AuthJsonResult>()
    ..ref.status = status
    ..ref.json = json;
}

